import{c as e,Q as a,j as l,m as r}from"./chunks/framework.DOi4mjdC.js";const d="/assets/%E5%9C%B0%E5%9D%80%E9%87%8D%E5%8F%A0%E7%A4%BA%E4%BE%8B%EF%BC%88%E4%B8%8D%E6%94%AF%E6%8C%81%EF%BC%89.XPeiarSp.png",p=JSON.parse('{"title":"通用说明和约束","description":"","frontmatter":{},"headers":[{"level":1,"title":"通用说明和约束","slug":"通用说明和约束"},{"level":2,"title":"所需头文件和库文件","slug":"所需头文件和库文件"},{"level":2,"title":"逻辑位置和物理存储的映射关系","slug":"逻辑位置和物理存储的映射关系"},{"level":2,"title":"通用地址对齐约束","slug":"通用地址对齐约束"},{"level":2,"title":"通用地址重叠约束","slug":"通用地址重叠约束"}],"relativePath":"api/SIMD-API/通用说明和约束.md","filePath":"api/SIMD-API/通用说明和约束.md"}'),s={name:"api/SIMD-API/通用说明和约束.md"};function i(o,t,A,n,f,u){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="通用说明和约束" tabindex="-1">通用说明和约束 <a class="header-anchor" href="#通用说明和约束" aria-label="Permalink to &quot;通用说明和约束&quot;">​</a></h1><h2 id="所需头文件和库文件" tabindex="-1">所需头文件和库文件 <a class="header-anchor" href="#所需头文件和库文件" aria-label="Permalink to &quot;所需头文件和库文件&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>Ascend C API所在头文件目录为：</p><ul><li>基础API：${INSTALL_DIR}/include/ascendc/basic_api/interface</li><li>高阶API：（注意，如下目录头文件中包含的接口如果未在资料中声明，属于间接调用接口，开发者无需关注）</li><li>${INSTALL_DIR}/include/ascendc/highlevel_api/lib</li><li>${INSTALL_DIR}/include/tiling ${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。 使用Ascend C API依赖的库文件说明如下：</li><li>基础API：不涉及</li><li>高阶API：因高阶API配套Host Tiling接口，需要链接libtiling_api.a。</li></ul></div><p>为方便开发者使用，Ascend C基础API和高阶API均支持通过包含kernel_operator.h文件来调用相应接口。如无特殊说明，包含该头文件即可满足接口调用需求。若API文档中有特殊说明，则应遵循API的具体说明。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;kernel_operator.h&quot;</span></span></code></pre></div><h2 id="逻辑位置和物理存储的映射关系" tabindex="-1">逻辑位置和物理存储的映射关系 <a class="header-anchor" href="#逻辑位置和物理存储的映射关系" aria-label="Permalink to &quot;逻辑位置和物理存储的映射关系&quot;">​</a></h2><p>Ascend C API的操作数通常为<a href="./基础数据结构/GlobalTensor/GlobalTensor.html">GlobalTensor</a>和<a href="./基础数据结构/LocalTensor/LocalTensor.html">LocalTensor</a>，Tensor数据的存储位置均使用逻辑位置（<a href="./其他数据类型/TPosition.html">TPosition</a>）来表达，从而隐藏了硬件架构的差异。TPosition类型包括：VECIN、VECOUT、VECCALC、A1、A2、B1、B2、CO1、CO2等，其与物理内存的映射关系如下表所示。</p><p><strong>表 1</strong> TPosition与物理内存映射关系</p><table tabindex="0"><thead><tr><th>TPosition</th><th>物理内存</th></tr></thead><tbody><tr><td>GM</td><td>Global Memory</td></tr><tr><td>VECIN</td><td>Unified Buffer</td></tr><tr><td>VECCALC</td><td>Unified Buffer</td></tr><tr><td>VECOUT</td><td>Unified Buffer</td></tr><tr><td>A1</td><td>L1 Buffer</td></tr><tr><td>A2</td><td>L0A Buffer</td></tr><tr><td>B1</td><td>L1 Buffer</td></tr><tr><td>B2</td><td>L0B Buffer</td></tr><tr><td>C1</td><td>Ascend 950PR/Ascend 950DT，L1 Buffer。 Atlas 训练系列产品，Unified Buffer。 Atlas 推理系列产品AI Core，Unified Buffer。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，L1 Buffer。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，L1 Buffer。 Atlas 200I/500 A2 推理产品，Unified Buffer。</td></tr><tr><td>C2</td><td>Ascend 950PR/Ascend 950DT，BiasTable Buffer。 Atlas 训练系列产品，L0C Buffer。 Atlas 推理系列产品AI Core，L0C Buffer。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，BiasTable Buffer。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，BiasTable Buffer。 Atlas 200I/500 A2 推理产品，BiasTable Buffer。</td></tr><tr><td>CO1</td><td>L0C Buffer</td></tr><tr><td>CO2</td><td>Ascend 950PR/Ascend 950DT，Global Memory。 Atlas 训练系列产品，Unified Buffer。 Atlas 推理系列产品AI Core，Unified Buffer。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，Global Memory。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，Global Memory。 Atlas 200I/500 A2 推理产品，Global Memory。</td></tr><tr><td>TSCM</td><td>L1 Buffer</td></tr><tr><td>SPM</td><td>Ascend 950PR/Ascend 950DT，Global Memory。 Atlas 训练系列产品，L1 Buffer。 Atlas 推理系列产品AI Core，L1 Buffer。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，Global Memory。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，Global Memory。</td></tr><tr><td>C2PIPE2GM</td><td>Ascend 950PR/Ascend 950DT，Fixpipe Buffer。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，Fixpipe Buffer。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，Fixpipe Buffer。</td></tr></tbody></table><h2 id="通用地址对齐约束" tabindex="-1">通用地址对齐约束 <a class="header-anchor" href="#通用地址对齐约束" aria-label="Permalink to &quot;通用地址对齐约束&quot;">​</a></h2><p>AI Core上的存储单元用于存储矢量计算、矩阵计算的源操作数和目的操作数，各类存储单元的对齐要求如<a href="#table16278354141117">表2</a>所示，因此Ascend C API操作数的起始地址对齐要求应与这些存储单元的对齐要求保持一致。<strong>需要注意的是，如果接口中已明确说明操作数起始地址对齐要求，则以具体API中的说明为准。</strong></p><p><strong>表 2</strong> 不同存储单元的对齐要求</p><table tabindex="0"><thead><tr><th>存储单元</th><th>对齐要求</th></tr></thead><tbody><tr><td>Global Memory</td><td>无对齐要求。</td></tr><tr><td>Unified Buffer</td><td>32Byte对齐。</td></tr><tr><td>L1 Buffer</td><td>32Byte对齐。</td></tr><tr><td>L0A Buffer/L0B Buffer</td><td>512Byte对齐。</td></tr><tr><td>L0C Buffer</td><td>64Byte对齐。</td></tr><tr><td>BiasTable Buffer</td><td>64Byte对齐。</td></tr><tr><td>Fixpipe Buffer</td><td>64Byte对齐。</td></tr></tbody></table><h2 id="通用地址重叠约束" tabindex="-1">通用地址重叠约束 <a class="header-anchor" href="#通用地址重叠约束" aria-label="Permalink to &quot;通用地址重叠约束&quot;">​</a></h2><p>使用基础API的Tensor高维切分计算接口时，为了节省地址空间，开发者可以定义一个Tensor，供源操作数与目的操作数同时使用（即地址重叠）。使用时需要注意以下约束：</p><ul><li>单次迭代内：源操作数与目的操作数必须100%完全重叠，不支持部分重叠。</li><li>多次迭代间：不支持前序迭代的目的操作数与后序迭代的源操作数重叠。例如，第N次迭代的目的操作数是第N+1次的源操作数（如下图所示）。在这种情况下，第N次迭代可能会改写覆盖源操作数的数值，导致无法得到预期结果。特别地，对于部分双目计算类的API（Add、Sub、Mul、Max、Min、AddRelu、SubRelu），当数据类型为half、int32_t、float时，支持前序迭代的目的操作数与后序迭代的源操作数重叠：仅针对目的操作数和第二个源操作数重叠的情况，且src1RepStride或者dstRepStride必须为0。</li></ul><p><strong>图 1</strong> 地址重叠示例（不支持）<br><img src="'+d+'" alt="" title="地址重叠示例（不支持）"></p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>本节所述地址重叠通用约束适用于一般情况，API参考中如有额外特殊说明的，则以具体API中的说明为准。 API中没有描述地址重叠约束的，视为不支持Tensor高维切分计算的地址重叠，地址重叠时计算结果可能不满足预期。</p></div>',18)])])}const B=e(s,[["render",i]]);export{p as __pageData,B as default};
